#include <stdexcept>
#include <string>
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
static_assert(std::numeric_limits<int>::max() >= 1000000000, "int must hold input range");
#include <vector>
struct Person { int height, weight; };
std::size_t tower_length(std::vector<Person> people) {
    std::sort(people.begin(),people.end(),[](const Person&a,const Person&b){
        return a.height!=b.height ? a.height<b.height : a.weight<b.weight;
    });
    std::vector<std::size_t> dp(people.size(),1);
    std::size_t best=0;
    for(std::size_t i=0;i<people.size();++i){
        for(std::size_t j=0;j<i;++j){
            // 두 수치가 모두 엄격히 작아야 합니다. 동률은 연결하지 않습니다.
            if(people[j].height<people[i].height && people[j].weight<people[i].weight)
                dp[i]=std::max(dp[i],dp[j]+1);
        }
        best=std::max(best,dp[i]);
    }
    return best;
}
// 공백으로 구분된 정수 토큰 전체를 검사합니다. 1+2를 두 수로 받지 않습니다.
bool read_integer_token(long long& value) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t i = (!token.empty() && (token[0] == '+' || token[0] == '-')) ? 1 : 0;
    if (i == token.size()) return false;
    for (; i < token.size(); ++i) if (token[i] < '0' || token[i] > '9') return false;
    try {
        std::size_t consumed = 0;
        value = std::stoll(token, &consumed, 10);
        return consumed == token.size();
    } catch (const std::invalid_argument&) { return false; }
      catch (const std::out_of_range&) { return false; }
}
int main(){
 long long n=0;if(!read_integer_token(n)||n<0||n>1000)return 1;std::vector<Person>p;
 for(long long i=0;i<n;++i){long long h=0,w=0;if((!read_integer_token(h)||!read_integer_token(w))||h<1||w<1||h>1000000000||w>1000000000)return 1;p.push_back({static_cast<int>(h),static_cast<int>(w)});}
 std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
 std::cout<<tower_length(p)<<'\n';return std::cout?0:1;
}
